  trackFireballProjectile(fireball, playerId, burnAudio) {
    let hasExploded = false;
    const maxFlightTime = 6000;
    const checkInterval = 50;
    let flightTime = 0;
    const trackingInterval = setInterval(() => {
      flightTime += checkInterval;
      if (!fireball.isSpawned || hasExploded) {
        clearInterval(trackingInterval);
        if (fireball._trailInterval) {
          clearInterval(fireball._trailInterval);
        }
        burnAudio.pause();
        return;
      }
      const fireballPos = fireball.position;
      const allPlayers = this.world.entityManager.getAllPlayerEntities().filter((entity) => entity instanceof SoccerPlayerEntity2);
      const hitPlayer = allPlayers.find((player) => {
        if (player.player.username === playerId)
          return false;
        const distance = Math.sqrt(Math.pow(player.position.x - fireballPos.x, 2) + Math.pow(player.position.y - fireballPos.y, 2) + Math.pow(player.position.z - fireballPos.z, 2));
        return distance <= 1.5;
      });
      const groundHit = fireballPos.y <= 0.5;
      if (hitPlayer || groundHit) {
        hasExploded = true;
        this.triggerFireballExplosion(fireballPos, playerId);
        clearInterval(trackingInterval);
        if (fireball._trailInterval) {
          clearInterval(fireball._trailInterval);
        }
        burnAudio.pause();
        if (fireball.isSpawned) {
          fireball.despawn();
        }
        return;
      }
      if (flightTime >= maxFlightTime || fireballPos.y < -15) {
        console.log(`\uD83D\uDD25 FIREBALL: Projectile expired or went out of bounds`);
        hasExploded = true;
        this.triggerFireballExplosion(fireballPos, playerId);
        clearInterval(trackingInterval);
        if (fireball._trailInterval) {
          clearInterval(fireball._trailInterval);
        }
        burnAudio.pause();
        if (fireball.isSpawned) {
          fireball.despawn();
        }
      }
    }, checkInterval);
  }
  triggerFireballExplosion(explosionPos, playerId) {
    console.log(`\uD83D\uDCA5 FIREBALL EXPLOSION at [${explosionPos.x.toFixed(2)}, ${explosionPos.y.toFixed(2)}, ${explosionPos.z.toFixed(2)}]!`);
    const explosionAudio = new PW({
      uri: "audio/sfx/damage/explode.mp3",
      loop: false,
      volume: 1,
      position: explosionPos,
      referenceDistance: 25
    });
    explosionAudio.play(this.world);
    this.registerTimer(setTimeout(() => {
      if (!this.isDestroyed) {
        const thunderAudio = new PW({
          uri: "audio/sfx/weather/thunder-strike-1.mp3",
          loop: false,
          volume: 0.7,
          position: explosionPos,
          referenceDistance: 30
        });
        thunderAudio.play(this.world);
      }
    }, 200), "timeout", playerId);
    this.registerTimer(setTimeout(() => {
      if (!this.isDestroyed) {
        const debrisAudio = new PW({
          uri: "audio/sfx/damage/glass-break-2.mp3",
          loop: false,
          volume: 0.5,
          position: explosionPos,
          referenceDistance: 15
        });
        debrisAudio.play(this.world);
      }
    }, 400), "timeout", playerId);
    const explosionEffect = new B8({
      name: "fireball-explosion",
      modelUri: "models/misc/firework.gltf",
      modelScale: 8,
      rigidBodyOptions: {
        type: rG.KINEMATIC_POSITION
      }
    });
    explosionEffect.spawn(this.world, explosionPos);
    const explosionRadius = 8;
    const allPlayers = this.world.entityManager.getAllPlayerEntities().filter((entity) => entity instanceof SoccerPlayerEntity2);
    const affectedPlayers = [];
    allPlayers.forEach((player) => {
      if (player.player.username === playerId)
        return;
      const distance = Math.sqrt(Math.pow(player.position.x - explosionPos.x, 2) + Math.pow(player.position.y - explosionPos.y, 2) + Math.pow(player.position.z - explosionPos.z, 2));
      if (distance <= explosionRadius) {
        const damageMultiplier = Math.max(0.3, 1 - distance / explosionRadius);
        this.applyExplosionDamage(player, explosionPos, damageMultiplier);
        affectedPlayers.push(player);
        console.log(`\uD83D\uDCA5 EXPLOSION HIT: ${player.player.username} (distance: ${distance.toFixed(2)}, multiplier: ${damageMultiplier.toFixed(2)})`);
      }
    });
    this.createFirePatches(explosionPos, 3);
    this.registerTimer(setTimeout(() => {
      if (!this.isDestroyed && explosionEffect.isSpawned) {
        explosionEffect.despawn();
      }
    }, 3000), "timeout", playerId);
    console.log(`\uD83D\uDCA5 FIREBALL EXPLOSION COMPLETE: Affected ${affectedPlayers.length} players`);
  }
  applyExplosionDamage(player, explosionPos, damageMultiplier) {
    const knockbackDirection = this.calculateKnockbackDirection(explosionPos, player.position);
    const baseKnockback = 15;
    const knockbackForce = baseKnockback * damageMultiplier;
    player.applyImpulse({
      x: knockbackDirection.x * knockbackForce * player.mass,
      y: 5 * damageMultiplier * player.mass,
      z: knockbackDirection.z * knockbackForce * player.mass
    });
    const burnDuration = Math.floor(3000 * damageMultiplier);
    this.applyBurnEffect(player, burnDuration);
    const damageAudio = new PW({
      uri: "audio/sfx/damage/fall-big.mp3",
      loop: false,
      volume: 0.6 * damageMultiplier,
      position: player.position,
      referenceDistance: 10
    });
    damageAudio.play(this.world);
  }
  applyBurnEffect(player, durationMs) {
    player._burnState = {
      isBurning: true,
      originalMass: player.mass,
      startTime: Date.now()
    };
    player.setAdditionalMass(300);
    const fireEffect = new B8({
      name: "burn-indicator",
      modelUri: "models/misc/selection-indicator.gltf",
      modelScale: 1.2,
      rigidBodyOptions: {
        type: rG.KINEMATIC_POSITION
      }
    });
    fireEffect.spawn(this.world, {
      x: player.position.x,
      y: player.position.y + 1.8,
      z: player.position.z
    });
    player._fireEffect = fireEffect;
    const burnAudio = new PW({
      uri: "audio/sfx/fire/fire-burning.mp3",
      loop: true,
      volume: 0.3,
      attachedToEntity: player,
      referenceDistance: 6
    });
    burnAudio.play(this.world);
    player._burnAudio = burnAudio;
    this.registerTimer(setTimeout(() => {
      if (!this.isDestroyed) {
        this.removeBurnEffect(player);
      }
    }, durationMs), "timeout", player.player.username);
    console.log(`\uD83D\uDD25 BURN APPLIED: ${player.player.username} burning for ${durationMs}ms`);
  }
  removeBurnEffect(player) {
    const burnState = player._burnState;
    if (!burnState || !burnState.isBurning) {
      return;
    }
    player.setAdditionalMass(0);
    const fireEffect = player._fireEffect;
    if (fireEffect && fireEffect.isSpawned) {
      fireEffect.despawn();
    }
    const burnAudio = player._burnAudio;
    if (burnAudio) {
      burnAudio.pause();
    }
    delete player._burnState;
    delete player._fireEffect;
    delete player._burnAudio;
    console.log(`\uD83D\uDD25 BURN REMOVED: ${player.player.username} recovered from burn`);
  }
  createFirePatches(centerPos, patchCount) {
    for (let i4 = 0;i4 < patchCount; i4++) {
      const angle = i4 / patchCount * 2 * Math.PI;
      const radius = 2 + Math.random() * 3;
      const firePatch = new B8({
        name: "fire-patch",
        modelUri: "models/misc/firework.gltf",
        modelScale: 2 + Math.random() * 1,
        rigidBodyOptions: {
          type: rG.KINEMATIC_POSITION
        }
      });
      firePatch.spawn(this.world, {
        x: centerPos.x + Math.cos(angle) * radius,
        y: centerPos.y + 0.2,
        z: centerPos.z + Math.sin(angle) * radius
      });
      const lifetime = 5000 + Math.random() * 3000;
      setTimeout(() => {
        if (firePatch.isSpawned) {
          firePatch.despawn();
        }
      }, lifetime);
    }
  }
