class BehaviorNode {
}

class Selector extends BehaviorNode {
  children;
  constructor(children) {
    super();
    this.children = children;
  }
  execute(agent) {
    for (const child of this.children) {
      if (child.execute(agent)) {
        return true;
      }
    }
    return false;
  }
}

class Sequence extends BehaviorNode {
  children;
  constructor(children) {
    super();
    this.children = children;
  }
  execute(agent) {
    for (const child of this.children) {
      if (!child.execute(agent)) {
        return false;
      }
    }
    return true;
  }
}

class Condition extends BehaviorNode {
  condition;
  constructor(condition) {
    super();
    this.condition = condition;
  }
  execute(agent) {
    return this.condition(agent);
  }
}

class Action extends BehaviorNode {
  action;
  constructor(action) {
    super();
    this.action = action;
  }
  execute(agent) {
    return this.action(agent);
  }
}
