      DEFENDER_MAX_POSSESSION_TIME: this.DEFENDER_MAX_POSSESSION_TIME,
      MIDFIELDER_MAX_POSSESSION_TIME: this.MIDFIELDER_MAX_POSSESSION_TIME,
