  isPassDirectionSafe(fromPosition, direction, distance) {
    const targetPosition = {
      x: fromPosition.x + direction.x * distance,
      y: fromPosition.y,
      z: fromPosition.z + direction.z * distance
    };
    const safeMinX = FIELD_MIN_X + 10;
    const safeMaxX = FIELD_MAX_X - 10;
    const safeMinZ = FIELD_MIN_Z + 10;
    const safeMaxZ = FIELD_MAX_Z - 10;
    const inBounds = targetPosition.x >= safeMinX && targetPosition.x <= safeMaxX && targetPosition.z >= safeMinZ && targetPosition.z <= safeMaxZ;
    if (!inBounds)
      return false;
    const opponents = this.team === "red" ? sharedState_default.getBlueAITeam() : sharedState_default.getRedAITeam();
    const INTERCEPTION_THRESHOLD = 4;
    for (const opponent of opponents) {
      if (!opponent.isSpawned)
        continue;
      const toOpponent = {
        x: opponent.position.x - fromPosition.x,
        z: opponent.position.z - fromPosition.z
      };
      const projectionLength = toOpponent.x * direction.x + toOpponent.z * direction.z;
      if (projectionLength >= 0 && projectionLength <= distance) {
        const projectedPoint = {
          x: fromPosition.x + direction.x * projectionLength,
          z: fromPosition.z + direction.z * projectionLength
        };
        const perpDistance = Math.sqrt(Math.pow(opponent.position.x - projectedPoint.x, 2) + Math.pow(opponent.position.z - projectedPoint.z, 2));
        if (perpDistance < INTERCEPTION_THRESHOLD) {
          return false;
        }
      }
    }
    return true;
  }
