class ItemThrowAbility {
  options;
  activeProjectiles = new Map;
  constructor(options) {
    this.options = options;
  }
  createProjectile(source) {
    const projectile = new B8({
      name: this.options.name,
      modelUri: this.options.modelUri,
      modelScale: this.options.modelScale,
      rigidBodyOptions: {
        type: rG.DYNAMIC,
        gravityScale: 0,
        enabledRotations: {
          x: true,
          y: true,
          z: true
        }
      },
      parent: source,
      parentNodeName: "hand_right_anchor"
    });
    const playerId = source instanceof w7 ? source.player.username : "unknown";
    this.activeProjectiles.set(playerId, projectile);
    return projectile;
  }
  use(origin, direction, source) {
    if (!source.world || !(source instanceof SoccerPlayerEntity2))
      return;
    const projectile = this.createProjectile(source);
    projectile.spawn(source.world, { x: 0, y: -0.3, z: 0.2 });
    source.startModelOneshotAnimations(["chuck"]);
    source.abilityHolder.removeAbility();
    source.abilityHolder.hideAbilityUI(source.player);
    setTimeout(() => {
      if (!source.world)
        return;
      projectile.despawn();
      const directionVector = new MW(direction.x, direction.y, direction.z).normalize();
      const spawnPosition = {
        x: source.position.x + directionVector.x * 1,
        y: source.position.y + 0.8,
        z: source.position.z + directionVector.z * 1
      };
      const throwProjectile = new B8({
        name: this.options.name,
        modelUri: this.options.modelUri,
        modelScale: this.options.modelScale,
        modelAnimationsPlaybackRate: 2.8,
        modelLoopedAnimations: ["spin"],
        rigidBodyOptions: {
          type: rG.DYNAMIC,
          gravityScale: 0
        }
      });
      throwProjectile.spawn(source.world, spawnPosition);
      this.launchProjectile(throwProjectile, direction, source);
    }, 500);
  }
  getIcon() {
    return this.options.icon;
  }
  launchProjectile(projectile, direction, source) {
    if (!projectile.isSpawned)
      return;
    const directionVector = new MW(direction.x, direction.y, direction.z).normalize();
    const velocityVector = directionVector.scale(this.options.speed);
    projectile.setLinearVelocity(velocityVector);
    projectile.createAndAddChildCollider({
      shape: P3.BALL,
      radius: this.options.projectileRadius,
      isSensor: true,
      collisionGroups: {
        belongsTo: [B$.ENTITY],
        collidesWith: [B$.PLAYER, B$.ENTITY]
      },
      onCollision: (otherEntity, started) => {
        if (!started || otherEntity === source || !(otherEntity instanceof SoccerPlayerEntity2))
          return;
        if (otherEntity.isDodging) {
          return;
        }
        otherEntity.stunPlayer();
        projectile.despawn();
        const playerId = source instanceof w7 ? source.player.username : "unknown";
        this.activeProjectiles.delete(playerId);
      }
    });
    let age = 0;
    projectile.on(mz.TICK, ({ entity, tickDeltaMs }) => {
      age += tickDeltaMs / 1000;
      const currentVelocity = entity.linearVelocity;
      if (currentVelocity.x !== 0 || currentVelocity.y !== 0 || currentVelocity.z !== 0) {
        projectile.setRotation(this.faceDirection(currentVelocity));
      }
      if (age >= this.options.lifeTime) {
        projectile.despawn();
        const playerId = source instanceof w7 ? source.player.username : "unknown";
        this.activeProjectiles.delete(playerId);
      }
    });
  }
  faceDirection(wantedDirection) {
    const direction = MW.fromVector3Like(wantedDirection).normalize();
    const yaw = Math.atan2(direction.x, direction.z);
    const pitch = Math.asin(direction.y);
    const halfYaw = yaw * 0.5;
    const halfPitch = -pitch * 0.5;
    const cosY = Math.cos(halfYaw);
    const sinY = Math.sin(halfYaw);
    const cosP = Math.cos(halfPitch);
    const sinP = Math.sin(halfPitch);
    return {
      x: sinP * cosY,
      y: sinY * cosP,
      z: -sinY * sinP,
      w: cosY * cosP
    };
  }
}

