// abilities/TimeSlowAbility.ts
init_server();
init_SoccerPlayerEntity();
init_gameModes();

class TimeSlowAbility {
  options;
  constructor(options) {
    this.options = options;
  }
  getIcon() {
    return this.options.icon;
  }
  use(origin, direction, source) {
    console.log(`\uD83D\uDD50 TIME SLOW: use() method called!`);
    console.log(`\uD83D\uDD50 TIME SLOW: origin=${JSON.stringify(origin)}, direction=${JSON.stringify(direction)}, source=${source.constructor.name}`);
    if (!isArcadeMode()) {
      console.log("\uD83D\uDD50 TIME SLOW: Power-up blocked - not in arcade mode");
      if (source instanceof SoccerPlayerEntity2 && source.player.ui && typeof source.player.ui.sendData === "function") {
        source.player.ui.sendData({
          type: "action-feedback",
          feedbackType: "error",
          title: "Mode Required",
          message: "Enhanced power-ups only work in Arcade Mode! Use '/arcade' to switch modes."
        });
      }
      if (source instanceof SoccerPlayerEntity2) {
        source.abilityHolder.removeAbility();
        source.abilityHolder.hideAbilityUI(source.player);
      }
      return;
    }
    if (!source.world || !(source instanceof SoccerPlayerEntity2)) {
      console.error("❌ TIME SLOW: Invalid source entity for time slow ability");
      console.error(`❌ TIME SLOW: source.world=${!!source.world}, instanceof SoccerPlayerEntity=${source instanceof SoccerPlayerEntity2}`);
      return;
    }
    console.log(`\uD83D\uDD50 TIME SLOW: ${source.player.username} activating time manipulation in arcade mode`);
    this.playTimeActivationEffect(source);
    this.applyTimeSlowEffects(source);
    this.createTimeDistortionEffect(source);
    try {
      if (source.abilityHolder) {
        source.abilityHolder.removeAbility();
        source.abilityHolder.hideAbilityUI(source.player);
      }
    } catch (abilityError) {
      console.error("❌ TIME SLOW: Failed to remove ability from holder:", abilityError);
    }
    console.log(`✅ TIME SLOW: Successfully applied time manipulation to all opponents`);
  }
  playTimeActivationEffect(player) {
    try {
      if (!player.world) {
        console.error("❌ TIME SLOW: Player world not available for audio");
        return;
      }
      const timeActivationAudio = new PW({
        uri: "audio/sfx/ui/inventory-grab-item.mp3",
        loop: false,
        volume: 1,
        attachedToEntity: player
      });
      timeActivationAudio.play(player.world);
      setTimeout(() => {
        if (!player.world)
          return;
        const etherealAudio = new PW({
          uri: "audio/sfx/liquid/large-splash.mp3",
          loop: false,
          volume: 0.6,
          position: player.position,
          referenceDistance: 20
        });
        etherealAudio.play(player.world);
      }, 500);
      console.log(`\uD83D\uDD0A TIME SLOW: Played time activation effects for ${player.player.username}`);
    } catch (error) {
      console.error("❌ TIME SLOW AUDIO ERROR:", error);
    }
  }
  applyTimeSlowEffects(caster) {
    try {
      const duration = this.options.damage;
      const timeScale = this.options.speed;
      const allPlayers = caster.world.entityManager.getAllPlayerEntities().filter((entity) => entity instanceof SoccerPlayerEntity2);
      const affectedPlayers = [];
      allPlayers.forEach((player) => {
        if (player.player.username === caster.player.username) {
          return;
        }
        this.applyTimeSlowToPlayer(player, duration, timeScale);
        affectedPlayers.push(player);
        console.log(`\uD83D\uDD50 TIME SLOW: Applied time distortion to ${player.player.username}`);
      });
      if (caster.player.ui && typeof caster.player.ui.sendData === "function") {
        caster.player.ui.sendData({
          type: "power-up-activated",
          powerUpType: "time-slow",
          message: `Time Slow Active! ${affectedPlayers.length} players slowed for ${duration / 1000}s`,
          duration,
          icon: this.options.icon
        });
      }
      console.log(`\uD83D\uDD50 TIME SLOW: Applied time distortion to ${affectedPlayers.length} players`);
    } catch (error) {
      console.error("❌ TIME SLOW EFFECTS ERROR:", error);
    }
  }
  applyTimeSlowToPlayer(player, durationMs, timeScale) {
    try {
      const customProps = player.customProperties || new Map;
      player.customProperties = customProps;
      customProps.set("hasTimeSlowEffect", true);
      customProps.set("timeSlowScale", timeScale);
      customProps.set("timeSlowEndTime", Date.now() + durationMs);
      customProps.set("originalMovementScale", 1);
      this.createPlayerTimeEffect(player);
      console.log(`⏰ TIME SLOW: Applied ${Math.round((1 - timeScale) * 100)}% speed reduction for ${durationMs / 1000} seconds`);
      setTimeout(() => {
        try {
          if (customProps) {
            customProps.set("hasTimeSlowEffect", false);
            customProps.delete("timeSlowScale");
            customProps.delete("timeSlowEndTime");
            customProps.delete("originalMovementScale");
            this.removePlayerTimeEffect(player);
            if (player.player.ui && typeof player.player.ui.sendData === "function") {
              player.player.ui.sendData({
                type: "power-up-expired",
                powerUpType: "time-slow",
                message: "Time flow restored to normal"
              });
            }
            console.log(`⏰ TIME SLOW: Effect expired for ${player.player.username}`);
          }
        } catch (error) {
          console.error("❌ TIME SLOW CLEANUP ERROR:", error);
        }
      }, durationMs);
    } catch (error) {
      console.error("❌ TIME SLOW PLAYER ERROR:", error);
    }
  }
  createTimeDistortionEffect(player) {
    try {
      if (!player.world) {
        console.error("❌ TIME SLOW: Player world not available for visual effects");
        return;
      }
      const clockEffect = new B8({
        name: "time-distortion-clock",
        modelUri: this.options.modelUri,
        modelScale: this.options.modelScale * 2,
        rigidBodyOptions: {
          type: "KINEMATIC_POSITION",
          colliders: []
        }
      });
      const effectPosition = {
        x: player.position.x,
        y: player.position.y + 3,
        z: player.position.z
      };
      clockEffect.spawn(player.world, effectPosition);
      this.createTimeRipples(player.position, player.world);
      this.animateTimeDistortion(clockEffect);
      console.log(`✨ TIME SLOW: Created time distortion effects for ${player.player.username}`);
    } catch (error) {
      console.error("❌ TIME SLOW VISUAL EFFECT ERROR:", error);
    }
  }
  createTimeRipples(centerPos, world) {
    const rippleCount = 6;
    const maxRadius = 15;
    for (let i4 = 0;i4 < rippleCount; i4++) {
      const angle = i4 / rippleCount * Math.PI * 2;
      const radius = 5 + i4 * 2;
      const ripple = new B8({
        name: `time-ripple-${i4}`,
        modelUri: "models/misc/selection-indicator.gltf",
        modelScale: 3 + i4,
        rigidBodyOptions: {
          type: "KINEMATIC_POSITION",
          colliders: []
        }
      });
      const ripplePos = {
        x: centerPos.x + Math.cos(angle) * radius,
        y: centerPos.y + 0.2,
        z: centerPos.z + Math.sin(angle) * radius
      };
      ripple.spawn(world, ripplePos);
      this.animateRipple(ripple, i4 * 300);
    }
  }
  animateRipple(ripple, delay) {
    setTimeout(() => {
      let animationTime = 0;
      const maxAnimationTime = 2000;
      const startScale = ripple.modelScale;
      const animateFrame = () => {
        if (!ripple.isSpawned || animationTime >= maxAnimationTime) {
          if (ripple.isSpawned) {
            ripple.despawn();
          }
          return;
        }
        try {
          const progress = animationTime / maxAnimationTime;
          const scale = startScale * (1 + progress * 2);
          const fadeOffset = progress * -2;
          const currentPos = ripple.position;
          ripple.setPosition({
            x: currentPos.x,
            y: currentPos.y + fadeOffset * 0.1,
            z: currentPos.z
          });
          animationTime += 100;
          setTimeout(animateFrame, 100);
        } catch (error) {
          console.error("❌ TIME RIPPLE ANIMATION ERROR:", error);
          if (ripple.isSpawned) {
            ripple.despawn();
          }
        }
      };
      animateFrame();
    }, delay);
  }
  animateTimeDistortion(clockEffect) {
    let animationTime = 0;
    const maxAnimationTime = 8000;
    const animateFrame = () => {
      if (!clockEffect.isSpawned || animationTime >= maxAnimationTime) {
        if (clockEffect.isSpawned) {
          clockEffect.despawn();
        }
        return;
      }
      try {
        const rotationSpeed = 0.01;
        const yRotation = animationTime * rotationSpeed % (Math.PI * 2);
        clockEffect.setRotation({
          x: 0,
          y: Math.sin(yRotation / 2),
          z: 0,
          w: Math.cos(yRotation / 2)
        });
        const floatOffset = Math.sin(animationTime * 0.002) * 0.5;
        const currentPos = clockEffect.position;
        clockEffect.setPosition({
          x: currentPos.x,
          y: currentPos.y + floatOffset * 0.1,
          z: currentPos.z
        });
        animationTime += 100;
        setTimeout(animateFrame, 100);
      } catch (error) {
        console.error("❌ TIME DISTORTION ANIMATION ERROR:", error);
        if (clockEffect.isSpawned) {
          clockEffect.despawn();
        }
      }
    };
    animateFrame();
  }
  createPlayerTimeEffect(player) {
    try {
      const slowEffect = new B8({
        name: "player-time-slow",
        modelUri: "models/misc/selection-indicator.gltf",
        modelScale: 1.2,
        rigidBodyOptions: {
          type: "KINEMATIC_POSITION",
          colliders: []
        }
      });
      slowEffect.spawn(player.world, {
        x: player.position.x,
        y: player.position.y + 2.2,
        z: player.position.z
      });
      player._timeSlowEffect = slowEffect;
    } catch (error) {
      console.error("❌ PLAYER TIME EFFECT ERROR:", error);
    }
  }
  removePlayerTimeEffect(player) {
    try {
      const slowEffect = player._timeSlowEffect;
      if (slowEffect && slowEffect.isSpawned) {
        slowEffect.despawn();
      }
      delete player._timeSlowEffect;
    } catch (error) {
      console.error("❌ REMOVE TIME EFFECT ERROR:", error);
    }
  }
}

// abilities/BallMagnetAbility.ts
init_server();
init_SoccerPlayerEntity();
init_gameModes();
init_sharedState();

class BallMagnetAbility {
  options;
  constructor(options) {
    this.options = options;
  }
  getIcon() {
    return this.options.icon;
  }
  use(origin, direction, source) {
    if (!isArcadeMode()) {
      console.log("\uD83E\uDDED BALL MAGNET: Power-up blocked - not in arcade mode");
      if (source instanceof SoccerPlayerEntity2 && source.player.ui && typeof source.player.ui.sendData === "function") {
        source.player.ui.sendData({
          type: "action-feedback",
          feedbackType: "error",
          title: "Mode Required",
          message: "Enhanced power-ups only work in Arcade Mode! Use '/arcade' to switch modes."
        });
      }
      if (source instanceof SoccerPlayerEntity2) {
        source.abilityHolder.removeAbility();
        source.abilityHolder.hideAbilityUI(source.player);
      }
      return;
    }
    if (!source.world || !(source instanceof SoccerPlayerEntity2)) {
      console.error("❌ BALL MAGNET: Invalid source entity for ball magnet ability");
      return;
    }
    console.log(`\uD83E\uDDED BALL MAGNET: ${source.player.username} activating ball magnetism in arcade mode`);
    this.playMagnetActivationEffect(source);
    this.applyBallMagnetEffects(source);
    this.createMagneticFieldEffect(source);
    source.abilityHolder.removeAbility();
    source.abilityHolder.hideAbilityUI(source.player);
    console.log(`✅ BALL MAGNET: Successfully activated ball magnetism for ${source.player.username}`);
  }
  playMagnetActivationEffect(player) {
    try {
      if (!player.world) {
        console.error("❌ BALL MAGNET: Player world not available for audio");
        return;
      }
      const magnetActivationAudio = new PW({
        uri: "audio/sfx/ui/inventory-grab-item.mp3",
        loop: false,
        volume: 1,
        attachedToEntity: player
      });
      magnetActivationAudio.play(player.world);
      setTimeout(() => {
        if (!player.world)
          return;
        const electromagneticAudio = new PW({
          uri: "audio/sfx/dig/dig-grass.mp3",
          loop: false,
          volume: 0.7,
          position: player.position,
          referenceDistance: 15
        });
        electromagneticAudio.play(player.world);
      }, 300);
      console.log(`\uD83D\uDD0A BALL MAGNET: Played magnetic activation effects for ${player.player.username}`);
    } catch (error) {
      console.error("❌ BALL MAGNET AUDIO ERROR:", error);
    }
  }
  applyBallMagnetEffects(caster) {
    try {
      const duration = this.options.damage;
      const magnetForce = this.options.speed;
      const magnetRadius = this.options.projectileRadius;
      const soccerBall = sharedState_default.getSoccerBall();
      if (!soccerBall?.isSpawned) {
        console.error("❌ BALL MAGNET: Soccer ball not available");
        return;
      }
      const customProps = caster.customProperties || new Map;
      caster.customProperties = customProps;
      customProps.set("hasBallMagnetEffect", true);
      customProps.set("magnetForce", magnetForce);
      customProps.set("magnetRadius", magnetRadius);
      customProps.set("magnetEndTime", Date.now() + duration);
      const magnetInterval = setInterval(() => {
        if (!caster.isSpawned || !soccerBall.isSpawned) {
          clearInterval(magnetInterval);
          return;
        }
        const endTime = customProps.get("magnetEndTime");
        if (Date.now() > endTime) {
          clearInterval(magnetInterval);
          this.removeMagnetEffect(caster);
          return;
        }
        const distance = Math.sqrt(Math.pow(soccerBall.position.x - caster.position.x, 2) + Math.pow(soccerBall.position.y - caster.position.y, 2) + Math.pow(soccerBall.position.z - caster.position.z, 2));
        if (distance <= magnetRadius && distance > 1) {
          this.applyMagneticForce(soccerBall, caster, distance, magnetForce);
        }
      }, 50);
      caster._magnetInterval = magnetInterval;
      if (caster.player.ui && typeof caster.player.ui.sendData === "function") {
        caster.player.ui.sendData({
          type: "power-up-activated",
          powerUpType: "ball-magnet",
          message: `Ball Magnet Active! Ball follows you for ${duration / 1000}s`,
          duration,
          icon: this.options.icon
        });
      }
      setTimeout(() => {
        this.removeMagnetEffect(caster);
      }, duration);
      console.log(`\uD83E\uDDED BALL MAGNET: Applied ball magnetism for ${duration / 1000} seconds`);
    } catch (error) {
      console.error("❌ BALL MAGNET EFFECTS ERROR:", error);
    }
  }
  applyMagneticForce(ball, player, distance, baseForce) {
    try {
      const direction = {
        x: (player.position.x - ball.position.x) / distance,
        y: (player.position.y - ball.position.y) / distance,
        z: (player.position.z - ball.position.z) / distance
      };
      const forceMultiplier = Math.max(0.3, Math.min(1.5, baseForce / distance));
      const magneticForce = {
        x: direction.x * forceMultiplier,
        y: direction.y * forceMultiplier * 0.5,
        z: direction.z * forceMultiplier
      };
      ball.applyImpulse(magneticForce);
      const currentVelocity = ball.linearVelocity;
      ball.setLinearVelocity({
        x: currentVelocity.x * 0.9,
        y: currentVelocity.y * 0.95,
        z: currentVelocity.z * 0.9
      });
    } catch (error) {
      console.error("❌ MAGNETIC FORCE ERROR:", error);
    }
  }
  removeMagnetEffect(player) {
    try {
      const customProps = player.customProperties;
      if (customProps) {
        customProps.set("hasBallMagnetEffect", false);
        customProps.delete("magnetForce");
        customProps.delete("magnetRadius");
        customProps.delete("magnetEndTime");
      }
      const magnetInterval = player._magnetInterval;
      if (magnetInterval) {
        clearInterval(magnetInterval);
        delete player._magnetInterval;
      }
      this.removeMagneticFieldEffect(player);
      if (player.player.ui && typeof player.player.ui.sendData === "function") {
        player.player.ui.sendData({
          type: "power-up-expired",
          powerUpType: "ball-magnet",
          message: "Ball magnetism deactivated"
        });
      }
      console.log(`\uD83E\uDDED BALL MAGNET: Effect expired for ${player.player.username}`);
    } catch (error) {
      console.error("❌ MAGNET CLEANUP ERROR:", error);
    }
  }
  createMagneticFieldEffect(player) {
    try {
      if (!player.world) {
        console.error("❌ BALL MAGNET: Player world not available for visual effects");
        return;
      }
      const compassEffect = new B8({
        name: "magnetic-field-compass",
        modelUri: this.options.modelUri,
        modelScale: this.options.modelScale * 1.5,
        rigidBodyOptions: {
          type: "KINEMATIC_POSITION",
          colliders: []
        }
      });
      const effectPosition = {
        x: player.position.x,
        y: player.position.y + 2.5,
        z: player.position.z
      };
      compassEffect.spawn(player.world, effectPosition);
      this.createMagneticFieldLines(player.position, player.world);
      this.animateMagneticField(compassEffect, player);
      player._magneticFieldEffect = compassEffect;
      console.log(`✨ BALL MAGNET: Created magnetic field effects for ${player.player.username}`);
    } catch (error) {
      console.error("❌ BALL MAGNET VISUAL EFFECT ERROR:", error);
    }
  }
  createMagneticFieldLines(centerPos, world) {
    const lineCount = 8;
    const radius = this.options.projectileRadius;
    for (let i4 = 0;i4 < lineCount; i4++) {
      const angle = i4 / lineCount * Math.PI * 2;
      const fieldLine = new B8({
        name: `magnetic-field-line-${i4}`,
        modelUri: "models/misc/selection-indicator.gltf",
        modelScale: 0.8,
        rigidBodyOptions: {
          type: "KINEMATIC_POSITION",
          colliders: []
        }
      });
      const linePos = {
        x: centerPos.x + Math.cos(angle) * radius,
        y: centerPos.y + 0.5,
        z: centerPos.z + Math.sin(angle) * radius
      };
      fieldLine.spawn(world, linePos);
      this.animateFieldLine(fieldLine, angle, centerPos);
    }
  }
  animateFieldLine(fieldLine, angle, centerPos) {
    let animationTime = 0;
    const maxAnimationTime = 1e4;
    const radius = this.options.projectileRadius;
    const animateFrame = () => {
      if (!fieldLine.isSpawned || animationTime >= maxAnimationTime) {
        if (fieldLine.isSpawned) {
          fieldLine.despawn();
        }
        return;
      }
      try {
        const rotationSpeed = 0.002;
        const currentAngle = angle + animationTime * rotationSpeed;
        const pulseOffset = Math.sin(animationTime * 0.005) * 0.5;
        const currentRadius = radius + pulseOffset;
        const newPos = {
          x: centerPos.x + Math.cos(currentAngle) * currentRadius,
          y: centerPos.y + 0.5 + Math.sin(animationTime * 0.003) * 0.3,
          z: centerPos.z + Math.sin(currentAngle) * currentRadius
        };
        fieldLine.setPosition(newPos);
        animationTime += 100;
        setTimeout(animateFrame, 100);
      } catch (error) {
        console.error("❌ FIELD LINE ANIMATION ERROR:", error);
        if (fieldLine.isSpawned) {
          fieldLine.despawn();
        }
      }
    };
    animateFrame();
  }
  animateMagneticField(compassEffect, player) {
    let animationTime = 0;
    const maxAnimationTime = 1e4;
    const animateFrame = () => {
      if (!compassEffect.isSpawned || animationTime >= maxAnimationTime || !player.isSpawned) {
        if (compassEffect.isSpawned) {
          compassEffect.despawn();
        }
        return;
      }
      try {
        const newPos = {
          x: player.position.x,
          y: player.position.y + 2.5 + Math.sin(animationTime * 0.003) * 0.2,
          z: player.position.z
        };
        compassEffect.setPosition(newPos);
        const rotationSpeed = 0.02;
        const yRotation = animationTime * rotationSpeed % (Math.PI * 2);
        compassEffect.setRotation({
          x: 0,
          y: Math.sin(yRotation / 2),
          z: 0,
          w: Math.cos(yRotation / 2)
        });
        animationTime += 100;
        setTimeout(animateFrame, 100);
      } catch (error) {
        console.error("❌ MAGNETIC FIELD ANIMATION ERROR:", error);
        if (compassEffect.isSpawned) {
          compassEffect.despawn();
        }
      }
    };
    animateFrame();
  }
  removeMagneticFieldEffect(player) {
    try {
      const magneticEffect = player._magneticFieldEffect;
      if (magneticEffect && magneticEffect.isSpawned) {
        magneticEffect.despawn();
      }
      delete player._magneticFieldEffect;
    } catch (error) {
      console.error("❌ REMOVE MAGNETIC EFFECT ERROR:", error);
    }
  }
}

